create or replace function public.contribute_boss(p_boss_id uuid, p_source_event_id uuid, p_amount integer) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_user uuid := security.require_authenticated_user(); v_boss public.boss_encounters%rowtype; v_amount integer; begin if p_amount < 1 or p_amount > 1000 then raise exception 'Invalid contribution'; end if; select * into v_boss from public.boss_encounters where id=p_boss_id and user_id=v_user for update; if not found or v_boss.status <> 'active' then raise exception 'Boss encounter unavailable'; end if; if exists(select 1 from public.boss_contributions where boss_id=p_boss_id and source_event_id=p_source_event_id) then return jsonb_build_object('duplicate',true); end if; v_amount := least(p_amount, v_boss.health_remaining); insert into public.boss_contributions(boss_id,user_id,source_event_id,amount) values(p_boss_id,v_user,p_source_event_id,v_amount); update public.boss_encounters set health_remaining=health_remaining-v_amount,status=case when health_remaining-v_amount=0 then 'defeated' else status end where id=p_boss_id; return jsonb_build_object('duplicate',false,'amount',v_amount,'defeated',v_boss.health_remaining-v_amount=0); end; $$;
create or replace function public.settle_boss_reward(p_boss_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_user uuid := security.require_authenticated_user(); v_boss public.boss_encounters%rowtype; begin select * into v_boss from public.boss_encounters where id=p_boss_id and user_id=v_user for update; if not found or v_boss.status <> 'defeated' then raise exception 'Boss is not defeated'; end if; if v_boss.reward_claimed_at is not null then return jsonb_build_object('duplicate',true); end if; update public.boss_encounters set reward_claimed_at=now() where id=p_boss_id; insert into public.notifications(user_id,kind,title,message,route,metadata) values(v_user,'reward','Boss defeated','Your campaign milestone reward is ready.','/quests',jsonb_build_object('bossId',p_boss_id)); return jsonb_build_object('duplicate',false,'rewardDefinitionId',v_boss.reward_definition_id); end; $$;
revoke all on function public.contribute_boss(uuid,uuid,integer), public.settle_boss_reward(uuid) from public, anon; grant execute on function public.contribute_boss(uuid,uuid,integer), public.settle_boss_reward(uuid) to authenticated;
